package com.fasterxml.jackson.core;

import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser.NumberType;
import com.fasterxml.jackson.core.io.CharacterEscapes;
import com.fasterxml.jackson.core.util.VersionUtil;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicLong;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

/**
 * Unit tests for JsonGenerator.writeEmbeddedObject
 */
public class JsonGenerator_writeEmbeddedObject_TriageGen2Test {

    private JsonGenerator jsonGenerator;

    @Before
    public void setUp() {
        // Since JsonGenerator is abstract, we use Mockito to create a mock instance
        jsonGenerator = Mockito.mock(JsonGenerator.class);
    }

    /**
     * Tests the branch where the object is a byte array.
     * This covers the 'if (object instanceof byte[])' branch and the 'writeBinary' call.
     */
    @Test
    public void testWriteEmbeddedObject_WithByteArray() throws IOException {
        byte[] testData = new byte[]{0x01, 0x02, 0x03};

        jsonGenerator.writeEmbeddedObject(testData);

        // Verify that writeBinary was called with the exact byte array
        verify(jsonGenerator, times(1)).writeBinary(testData);
    }

    /**
     * Tests the branch where the object is NOT a byte array.
     * This covers the exception throwing logic and the JsonGenerationException.
     */
    @Test(expected = JsonGenerationException.class)
    public void testWriteEmbeddedObject_WithUnsupportedType() throws IOException {
        Object unsupportedObject = "This is a string, not a byte array";

        try {
            jsonGenerator.writeEmbeddedObject(unsupportedObject);
        } catch (JsonGenerationException e) {
            // Verify the exception message contains the class name as per implementation
            assert(e.getMessage().contains(unsupportedObject.getClass().getName()));
            throw e;
        }
    }

    /**
     * Tests the branch where the object is null.
     * Note: In the provided code, 'null instanceof byte[]' is false, 
     * so it should proceed to throw the JsonGenerationException.
     */
    @Test(expected = JsonGenerationException.class)
    public void testWriteEmbeddedObject_WithNull() throws IOException {
        jsonGenerator.writeEmbeddedObject(null);
    }

    /**
     * Tests a different unsupported type to ensure the exception is generic for non-byte types.
     */
    @Test(expected = JsonGenerationException.class)
    public void testWriteEmbeddedObject_WithInteger() throws IOException {
        jsonGenerator.writeEmbeddedObject(123);
    }
}
